# Generated by manage.py generate_test_cases.
from unittest.mock import patch
from types import SimpleNamespace

from django.contrib.auth import get_user_model
from django.http import HttpResponse

from bloomerp.services.sql_services import DatabaseTable, Field
from bloomerp.tests.base import (
    BloomerpAPIViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestAccessibleTablesView(BloomerpAPIViewTestCase):
    """Tests class `AccessibleTablesView` from `bloomerp/views/api/sql/accessible_tables.py`."""

    view_name = 'api_sql_accessible_tables'

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover SQL discovery metadata, filtering, and pagination contracts."""
        return [
            RequestScenario(
                name="Discovery returns canonical model labels and null join-table labels",
                user=self.admin_user,
                prepare=self.prepare_model_identities,
                expected=ExpectedResult(response_validators=self.model_identities_are_correct),
            ),
            RequestScenario(
                name="Field-only searches preserve canonical model labels",
                user=self.admin_user,
                query_params={"search": "benchmark_field"},
                prepare=self.prepare_model_identities,
                expected=ExpectedResult(response_validators=self.model_identities_are_correct),
            ),
            RequestScenario(
                name="Accessible table metadata omits field icons",
                description=(
                    "UC: A user loads SQL builder metadata.\n"
                    "Expected Result: API field metadata contains no UI icon classes."
                ),
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.field_icons_are_omitted),
            ),
            RequestScenario(
                name="Accessible tables search is applied before pagination",
                description=(
                    "UC: A user searches tables and requests the second result page.\n"
                    "Expected Result: Filtered pagination metadata and the requested table are returned."
                ),
                user=self.admin_user,
                query_params={
                    "search": "email",
                    "page": 2,
                    "page_size": 1,
                    "refresh": "true",
                },
                prepare=lambda scenario: self.patch_tables(
                    [
                        DatabaseTable(name="suppliers", fields=[Field(name="email", field_type="text")]),
                        DatabaseTable(name="customers", fields=[Field(name="email", field_type="text")]),
                        DatabaseTable(name="invoices", fields=[Field(name="customer_id", field_type="integer")]),
                    ]
                ),
                expected=ExpectedResult(response_validators=self.search_page_is_correct),
            ),
            RequestScenario(
                name="Accessible tables search matches field types",
                description=(
                    "UC: A user searches metadata by field type.\n"
                    "Expected Result: Only matching fields and their parent tables remain."
                ),
                user=self.admin_user,
                query_params={"search": "INTEGER"},
                prepare=lambda scenario: self.patch_tables(
                    [
                        DatabaseTable(
                            name="customers",
                            fields=[
                                Field(name="email", field_type="text"),
                                Field(name="age", field_type="integer"),
                            ],
                        )
                    ]
                ),
                expected=ExpectedResult(response_validators=self.integer_field_is_returned),
            ),
            RequestScenario(
                name="Accessible tables rejects invalid pagination",
                description=(
                    "UC: A user requests a page size above the maximum.\n"
                    "Expected Result: Query validation returns a 400 response."
                ),
                user=self.admin_user,
                query_params={"page_size": 101},
                expected=ExpectedResult(
                    status_code=400,
                    response_validators=self.key_in_json("page_size"),
                ),
            ),
        ]

    def prepare_model_identities(self, scenario: RequestScenario) -> None:
        """Supply permission-filtered models while exercising actual SQL metadata construction."""
        model = get_user_model()
        through = model._meta.get_field("groups").remote_field.through
        self.expected_model_labels = {
            model._meta.db_table: model._meta.label,
            through._meta.db_table: None,
        }
        field = SimpleNamespace(field="benchmark_field", field_type="CharField")
        self.identity_patcher = patch(
            "bloomerp.services.sql_services.UserPolicyManager.get_accessible_models_and_fields",
            return_value={model: [field], through: [field]},
        )
        self.identity_patcher.start()
        self.addCleanup(self.identity_patcher.stop)

    def model_identities_are_correct(self, response: HttpResponse) -> bool:
        """Check canonical labels are derived from models, including after field filtering."""
        try:
            tables = response.json()["databases"][0]["tables"]
            return {
                table["name"]: table["model_label"] for table in tables
            } == self.expected_model_labels
        finally:
            self.identity_patcher.stop()

    def patch_tables(self, tables):
        self.tables_patcher = patch(
            "bloomerp.views.api.sql.accessible_tables.SqlExecutor.get_accessible_tables_and_fields",
            return_value=tables,
        )
        self.tables_patcher.start()

    @staticmethod
    def field_icons_are_omitted(response):
        fields = [
            field
            for database in response.json()["databases"]
            for table in database["tables"]
            for field in table["fields"]
        ]
        return bool(fields) and all("icon" not in field for field in fields)

    def search_page_is_correct(self, response):
        try:
            payload = response.json()
            tables = payload["databases"][0]["tables"]
            return (
                [table["name"] for table in tables] == ["suppliers"]
                and payload["page"] == 2
                and payload["page_size"] == 1
                and payload["total_tables"] == 2
                and payload["total_pages"] == 2
                and not payload["has_next"]
                and payload["has_previous"]
                and payload["refreshed"]
            )
        finally:
            self.tables_patcher.stop()

    def integer_field_is_returned(self, response):
        try:
            fields = response.json()["databases"][0]["tables"][0]["fields"]
            return [field["name"] for field in fields] == ["age"]
        finally:
            self.tables_patcher.stop()
